package com.smartexam.mapper;
import com.baomidou.mybatisplus.core.mapper.BaseMapper; import com.smartexam.entity.Submissions; import org.apache.ibatis.annotations.*;
@Mapper public interface SubmissionsMapper extends BaseMapper<Submissions> { @Select("SELECT * FROM submissions WHERE id=#{id} FOR UPDATE") Submissions selectByIdForUpdate(Long id); @Select("SELECT * FROM submissions WHERE exam_id = #{examId} AND student_id = #{studentId} LIMIT 1") Submissions selectByExamAndStudent(Long examId, Long studentId); @Select("SELECT * FROM submissions WHERE exam_id=#{examId} ORDER BY submit_time DESC,id DESC") java.util.List<Submissions> selectByExamId(Long examId); @Select("SELECT * FROM submissions WHERE student_id=#{studentId} AND score_published=1 ORDER BY published_at DESC,id DESC") java.util.List<Submissions> selectPublishedByStudent(Long studentId); }
